// Remove thb-app-css from loading
function child_remove_thb_app_css( $tag, $handle, $href, $media ) {
    if ( 'thb-app-css' === $handle ) {
        // Log in browser console
        echo "<script>console.log('child_remove_thb_app_css function ran: removed thb-app-css');</script>";
        return ''; // remove the CSS link
    }
    return $tag;
}
