// Custom Walker for Navigation Menu
class Custom_Walker_Nav_Menu extends Walker_Nav_Menu {
    public function start_el(&$output, $item, $depth = 0, $args = array(), $id = 0) {
        $classes = empty($item->classes) ? array() : (array) $item->classes;
        $class_names = join(' ', apply_filters('nav_menu_css_class', array_filter($classes), $item, $args));
        
        $is_current = in_array('current-menu-item', $classes) || in_array('current-category-ancestor', $classes);
        
        $output .= '<a href="' . esc_url($item->url) . '" class="px-4 py-2 text-sm font-medium ' . 
                   ($is_current ? 'text-wine-700 font-semibold' : 'text-gray-700 hover:text-wine-700') . 
                   ' transition-colors">' . esc_html($item->title) . '</a>';
    }
}

