/**
 * Save the embed code when the term is updated.
 */
function ilw_child_theme_save_term_embed_field($term_id) {
    if (isset($_POST['term_embed_code'])) {
        update_term_meta($term_id, 'term_embed_code', wp_kses_post($_POST['term_embed_code']));
    }
}
